sp_widget.client_script:
function widgetcontroller($scope, $timeout, $rootScope, spUtil) {
    var c = this;

    // Check URL parameters for deep-linking to specific tabs on load
    var searchParam = c.data.urlParams.search || c.data.urlParams.customer_code;
    var requestParam = c.data.urlParams.request_number;

    if (requestParam) {
        c.activeTab = 'request_detail';
    } else if (searchParam) {
        c.activeTab = 'customer360';
    } else {
        c.activeTab = 'overview';
    }

    // Map the internal keys to your NSH child widgets
    var WIDGETS = {
        approval_requests: ['approvalRequestsWidget', 'clm_nsh_approval_requests'],
        customer360:       ['customer360Widget',      'clm_nsh_customer_360'],
        request_detail:    ['requestDetailWidget',    'clm_nsh_request_detail']
    };
    var pending = {};

    function fetchWidget(tab, done) {
        var w = WIDGETS[tab];
        if (!w || c.data[w[0]] || pending[tab]) { if (done) done(); return; }
        pending[tab] = true;

        // Pass widget options dynamically
        var options = {};
        if (tab === 'customer360') {
            options.search = c.data.urlParams.search || c.data.urlParams.customer_code || '';
        } else if (tab === 'request_detail') {
            options.requestNumber = c.data.urlParams.request_number || '';
        } else if (tab === 'approval_requests') {
            options.filters = JSON.stringify({ segment: '', zone: '', region: '', depot: '', period: 'latest' });
        }

        spUtil.get(w[1], options).then(function(response) {
            c.data[w[0]] = response;
            pending[tab] = false;
            if (done) done();
        }, function() { pending[tab] = false; if (done) done(); });
    }

    c.isTabReady = function() {
        var w = WIDGETS[c.activeTab];
        return !w || !!c.data[w[0]];
    };

    c.switchTab = function(tabName) {
        c.activeTab = tabName;
        fetchWidget(tabName);   // if prefetch hasn't finished, load immediately
    };

    var offSwitch = $rootScope.$on('clm.switch.tab', function(event, tabName) { c.switchTab(tabName); });

    // If deep-linked directly to a tab, fetch it immediately on load
    if (c.activeTab !== 'overview') {
        fetchWidget(c.activeTab);
    }

    // Prefetch other tabs one by one ONLY after the portfolio has finished loading
    var prefetched = false;
    function prefetchOthers() {
        if (prefetched) return;
        prefetched = true;
        var tabs = Object.keys(WIDGETS);
        (function next(i) { if (i < tabs.length) fetchWidget(tabs[i], function() { next(i + 1); }); })(0);
    }

    // Listens for the portfolio widget to announce it has finished its initial data load
    var offLoaded = $rootScope.$on('clm.portfolio.loaded', function() { $timeout(prefetchOthers, 300); });
    $timeout(prefetchOthers, 10000); // safety net

    $scope.$on('$destroy', function() { offSwitch(); offLoaded(); });
}

sp_widget.css:
.clm-dash {
  font-family: "Helvetica Neue", Arial, sans-serif;
  color: #1f2933;
  background: #f4f5f7;
  padding-bottom: 24px;
}

/* ---------- Breadcrumb ---------- */
.clm-breadcrumb {
  padding: 10px 20px;
  font-size: 13px;
  color: #5b6470;
  background: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* ---------- Tabs ---------- */
.clm-tabs {
  display: flex;
  gap: 28px;
  padding: 0 20px;
  background: #fff;
  border-bottom: 1px solid #e3e6eb;
}
.clm-tab {
  padding: 12px 2px;
  color: #6b7280;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  border-bottom: 3px solid transparent;
  text-decoration: none;
}
.clm-tab:hover { color: #374151; text-decoration: none; }
.clm-tab.active { color: #14141a; border-bottom-color: #f5c500; }

/* ---------- Loading ---------- */
.clm-loading { text-align: center; padding: 20px; color: #8a93a0; font-size: 13px; }

sp_widget.script:
(function() {
    var CONFIG = {
        roleTable: 'x_birl3_clm_role_user_mapping',
        roleF: {
            user: 'u_user',
            role: 'u_role'
        }
    };

    var ROLE_SEGMENT_MAP = {
        'NSH': 'Cement',
        'HEAD_RMC': 'RMC',
        'HEAD_KEY_CH_RMC': 'RMC',
        'HSBPD': 'BPD',
        'HBPD': 'BPD'
    };

    // =========================================================
    // STEP 1: Confirm Access (Check if user has a mapped role)
    // =========================================================
    var isAuthorized = false;
    var assignedRole = '';

    var grRole = new GlideRecord(CONFIG.roleTable);
    grRole.addQuery(CONFIG.roleF.user, gs.getUserID());
    grRole.query();

    while (grRole.next()) {
        var rv = String(grRole.getValue(CONFIG.roleF.role) || '').toUpperCase().trim();
        var rd = String(grRole.getDisplayValue(CONFIG.roleF.role) || '').toUpperCase().trim();

        // If the user has any role present in our map, authorize them
        if (ROLE_SEGMENT_MAP[rv] || ROLE_SEGMENT_MAP[rd]) {
            isAuthorized = true;
            assignedRole = rd || rv; // Capture the user's role for the UI
            break;
        }
    }

    // Capture URL params so the Client Script can lazy-load deep links properly
    data.urlParams = {
        search: $sp.getParameter('search') || '',
        customer_code: $sp.getParameter('customer_code') || '',
        request_number: $sp.getParameter('request_number') || ''
    };

    // Keeps backward compatibility if any embedded widget still checks this
    data.isNSH = isAuthorized; 

    data.viewLabel = assignedRole || 'Unauthorized';
    data.userName  = gs.getUserDisplayName();

    data.role = {
        role: assignedRole || 'Unauthorized',
        viewLabel: assignedRole || 'Unauthorized',
        userName: data.userName
    };

    // =========================================================
    // Embed child widgets
    // =========================================================

    // Only load the initial Portfolio widget upfront! The rest are lazy-loaded via the Client Script.
    data.portfolioWidget = $sp.getWidget('clm_nsh_portfolio', {
        filters: JSON.stringify({ segment: '', zone: '', region: '', depot: '', period: 'latest' })
    });

})();
